// Updates (main: lib/updater.cjs). The installed copy downloads in the background and installs only on the user's click;
// a portable copy only says a new version exists and opens the release page. Re-drawn on every state broadcast.
function updateStatusText(u){if(!u)return '';const v=u.downloadedVersion||u.latestVersion||'';const blocked=tr('Windows 보안(스마트 앱 컨트롤 등)이 설치를 막았어요. 잠시 뒤 다시 시도해 주세요.');switch(u.status){case 'checking':return tr('새 버전을 확인하는 중…');case 'up-to-date':return tr('최신 버전이에요.');case 'available':return u.selfUpdating?tr("새 버전 {0}을(를) 받을 수 있어요.", [v]):tr("새 버전 {0}이(가) 나왔어요. 설치 파일로 설치하면 다음부터 자동으로 업데이트돼요.", [v]);case 'downloading':return tr("{0} 내려받는 중… {1}%", [v,u.percent??0]);case 'downloaded':return u.error==='blocked'?blocked:tr("{0} 준비 완료. 다시 시작하면 적용돼요.", [v]);case 'error':return ({network:tr('인터넷 연결을 확인해 주세요.'),'no-release':tr('아직 공개된 업데이트가 없어요.'),blocked,integrity:tr('내려받은 파일을 확인하지 못했어요. 다시 확인해 주세요.'),permission:tr('설치 폴더에 쓸 권한이 없어요.')})[u.error]||tr('업데이트를 확인하지 못했어요.');case 'unsupported':return tr('이 사본은 자동 업데이트를 쓸 수 없어요.');default:return u.enabled?tr('새 버전을 자동으로 확인해요.'):tr('자동 확인이 꺼져 있어요.');}}
// 2026-10-21 user: 「업데이트 기록 이거 굳이 필요할까?」 — no standing history link; 「새 기능 보기」 only while a new version is on its way.
function updateBlock(){const u=state.app?.update||null;if(!u)return null;const v=u.downloadedVersion||u.latestVersion||'';const news=u.selfUpdating&&v&&['available','downloading','downloaded'].includes(u.status)?h('button',{type:'button',class:'text-button',onclick:()=>api.invoke('update:open',{}).catch(e=>toast(e.message,true))},tr('새 기능 보기')):null;const busy=['checking','downloading'].includes(u.status);let action;if(u.canInstall)action=btn(tr('지금 다시 시작해 적용'),e=>{e.currentTarget.disabled=true;run('update:install',{}).catch(()=>{});},'button primary');else if(u.canDownload)action=btn(tr('내려받기'),()=>run('update:download',{}).catch(()=>{}),'button primary');else if(!u.selfUpdating&&u.status==='available')action=btn(tr('설치 파일 받기'),()=>api.invoke('update:open',{}).catch(e=>toast(e.message,true)),'button primary');else action=btn(tr('업데이트 확인'),e=>{const b=e.currentTarget;b.disabled=true;api.invoke('update:check',{}).catch(err=>toast(err.message,true)).finally(()=>{b.disabled=false;});},'button subtle');if(busy)action.disabled=true;const auto=h('input',{type:'checkbox',checked:state.settings.autoUpdate!==false});auto.addEventListener('change',()=>run('settings:update',{autoUpdate:auto.checked}).catch(()=>{auto.checked=!auto.checked;}));return h('section',{class:'update-block',id:'update-block'},h('div',{class:'update-row'},h('span',{class:'update-status',role:'status'},updateStatusText(u)),action),h('div',{class:'update-row'},h('label',{class:'checkbox-field'},auto,tr('새 버전 자동 확인')),news));}
function refreshUpdateBlock(){const node=$('#update-block');if(!node)return;const inside=node.contains(document.activeElement);const next=updateBlock();node.replaceWith(next);if(inside)(next.querySelector('button:not(:disabled),input')||next).focus?.({preventScroll:true});}
api.invoke('state:get').then(s=>{state=D.visibleState(s);render();if(openDayPending)openDay(...openDayPending);if(!isWidget)setTimeout(tourMaybeStart,500);}).catch(e=>$('#app').replaceChildren(empty('info',tr('Dayboard를 열지 못했어요'),e.message,btn(tr('다시 시도'),()=>location.reload(),'button primary'))));
let renderedDay=D.dateKey();
// Re-render only when the calendar day changes; a full redraw every minute would reset scroll and interrupt typing.
setInterval(()=>{const today=D.dateKey();if(today!==renderedDay){if(selectedDate===renderedDay){selectedDate=today;month=D.fromDate(today);}renderedDay=today;render();}},60000);
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(state?.settings.theme==='system')render();});
